import {legacySummary,copyHeroLegacy,validHeroLegacies} from './hero-legacy.js?v=5.5.0';
import {CREW,defaultHero} from './mako.js?v=5.16.0';
import {APPROACHES} from './battle-approaches.js';
import {ORIGINS} from './origin-content.js?v=5.18.0';
export const PROFILE_PREFIX='ash-aether-journey-hero-';
export const THREADS=[
 {id:'shelter',name:'A place to return',item:'tonic',label:'One extra Tonic',text:'Begin with a remedy for a road companion. Your historical decisions still determine the services that survive.'},
 {id:'echo',name:'A voice to remember',item:'ether',label:'One extra Ether',text:'Begin with focus for another pattern. Listen to the people behind the mechanisms.'},
 {id:'second-chance',name:'Someone left behind',item:'revive',label:'One revival supply',text:'Begin with one way to bring a fallen companion back. It cannot be replenished by reopening the roster.'}
];
const clone=v=>JSON.parse(JSON.stringify(v));
export function journeyWeave(hero,seed=0){if(!Number.isInteger(hero)||!CREW[hero])throw Error('Unknown traveller');const numeric=Number(seed),n=Number.isFinite(numeric)?Math.min(Number.MAX_SAFE_INTEGER,Math.abs(Math.floor(numeric))):0;return {version:1,hero,seed:n,approach:APPROACHES[n%APPROACHES.length].id,thread:THREADS[Math.floor(n/APPROACHES.length)%THREADS.length].id};}
export function normalizeJourney(hero,value={}){const normalized=journeyWeave(hero,value.seed);if(APPROACHES.some(a=>a.id===value.approach))normalized.approach=value.approach;if(THREADS.some(t=>t.id===value.thread))normalized.thread=value.thread;return normalized;}
export function rerollJourney(hero,current,random=Math.random){const existing=normalizeJourney(hero,current),offset=1+Math.floor(Math.max(0,Math.min(.999999,Number(random())||0))*17);let next=journeyWeave(hero,(existing.seed+offset)%180000);if(next.approach===existing.approach&&next.thread===existing.thread)next=journeyWeave(hero,(next.seed+1)%180000);return next;}
export function applyJourneyKit(state,journey,hero=journey?.hero){if(!Number.isInteger(hero)||!CREW[hero]||!state.heroes?.[hero])return;const selected=normalizeJourney(hero,journey);state.journey=clone(selected);const h=state.heroes[hero],a=APPROACHES.find(a=>a.id===selected.approach),t=THREADS.find(t=>t.id===selected.thread);h.battleApproach=a.id;for(const item of a.items)state.items[item]=(state.items[item]||0)+1;state.items[t.item]=(state.items[t.item]||0)+1;}
export function profileHero(value){const s=value?.world;return s?.journey?.hero??s?.chronicle?.hero??s?.party?.[0]??0;}
export function validJourneyValue(value){const s=value?.world,hero=profileHero(value);return value?.schema==='ash-aether.enhanced-save/1'&&s?.schema==='ash-aether.engine2/1'&&validHeroLegacies(s.heroLegacies)&&Number.isInteger(hero)&&!!CREW[hero]&&Array.isArray(s.heroes)&&s.heroes.length===7&&s.heroes[hero]?.id===hero&&Array.isArray(s.party)&&s.party.length>0&&s.party.length<=3&&new Set(s.party).size===s.party.length&&s.party.every(id=>Number.isInteger(id)&&!!CREW[id])&&Number.isInteger(s.chapter)&&s.chapter>=1&&s.chapter<=25;}
export function writeJourneyProfile(storage,value,now=Date.now()){
 const hero=profileHero(value);if(!validJourneyValue(value))return false;
 try{storage.setItem(PROFILE_PREFIX+hero,JSON.stringify({version:1,hero,savedAt:now,value}));return true;}catch{return false;}
}
export function readJourneyProfiles(storage){return CREW.map((_,hero)=>{try{const p=JSON.parse(storage.getItem(PROFILE_PREFIX+hero));return p?.hero===hero&&profileHero(p.value)===hero&&validJourneyValue(p.value)?p:null;}catch{return null;}});}
export function profileSummary(profile){const s=profile?.value?.world;if(!validJourneyValue(profile?.value)||profile.hero!==profileHero(profile.value))return null;const o=ORIGINS.find(o=>o.id===s.chronicle?.originId),past=s.chronicle?.phase==='past';return {hero:profile.hero,ready:!past&&!s.fieldOrigins?.active&&s.mode==='field'&&!profile.value.battle,chapter:s.chapter,label:past?(o?.title||'Beginning')+' · '+Math.min(5,(s.chronicle.step||0)+1)+'/5':s.complete?'The restored world':'Chapter '+s.chapter,commissions:s.frontiers?.claimed?.length||0,originComplete:s.chronicle?.phase==='present',legacy:legacySummary(s,profile.hero)};}
/** Local drop-in: carry identity and discipline, never another save's money or quest flags. */
export function joinJourney(state,profile){const summary=profileSummary(profile),id=profile?.hero;if(!summary?.ready)throw Error('Finish this traveller’s beginning or encounter before joining.');if(state.mode!=='field'||state.chronicle?.phase==='past'||state.fieldOrigins?.active)throw Error('Companions meet on the shared road, after the beginning and between encounters.');if(state.party.includes(id))return {joined:false,reserved:null};
 const source=profile.value.world.heroes[id];if(!state.recruited.includes(id)){state.recruited.push(id);const level=Math.min(45,Math.max(1,...state.party.map(member=>Number(state.heroes[member]?.level)||1)));const hero=defaultHero(id,level);hero.battleApproach=normalizeJourney(id,{...profile.value.world.journey,approach:source.battleApproach||profile.value.world.journey?.approach}).approach;hero.learned|=128;hero.unlockedSlots=Math.max(1,state.story?.slots||1);hero.loadout=[{core:CREW[id].affinity,support:'focus'}];state.heroes[id]=hero;if(!state.cores.includes(CREW[id].affinity))state.cores.push(CREW[id].affinity);if(!state.supports.includes('focus'))state.supports.push('focus');}
 copyHeroLegacy(state,profile.value.world,id);
 const reserved=state.party.length>=3?state.party.pop():null;state.party.push(id);state.story?.journal?.push({id:'roster-join:'+id,chapter:state.chapter,title:CREW[id].name+' takes the shared road',text:'Their earlier life is preserved in their own journey. They join this crew at its current strength; its history, supplies and leader stay intact.'});return {joined:true,reserved};}
